<script setup lang="ts">
import {environments,paints,upholsteryColors,backgrounds,lightPresets,interiorDetails} from '~/data/finishes'
const s=useAtelier(),audio=useAudio(),{t}=useLocale(),ready=ref(false),progress=ref(0),error=ref(''),tab=ref('paint'),viewer=ref(0),cabinFinishes=ref(false)
const tabs=[{id:'paint',ru:'Кузов',en:'Paint'},{id:'interior',ru:'Салон',en:'Interior'},{id:'environment',ru:'Окружение',en:'Environment'},{id:'details',ru:'Детали',en:'Details'}]
const paintName=computed(()=>{const p=paints.find(p=>p.hex===s.paint.value);return p?t(p.ru,p.en):t('Индивидуальный цвет','Custom finish')})
const upholsteryName=computed(()=>{const p=upholsteryColors.find(p=>p.hex===s.upholstery.value);return p?t(p.ru,p.en):t('Графит','Graphite')})
const detail=computed(()=>interiorDetails.find(d=>d.id===s.detail.value))
watch(()=>s.interior.value,v=>{document.body.style.overflow=v?'hidden':'';cabinFinishes.value=false;if(v)tab.value='interior';else s.detail.value=''})
onBeforeUnmount(()=>{document.body.style.overflow='';s.interior.value=false;audio.stop()})
function action(fn:()=>void){fn();audio.click()}
async function focus(id:string){s.focus.value='';await nextTick();s.focus.value=id}
async function inspect(id:string){s.detail.value='';await nextTick();s.detail.value=id}
function retry(){error.value='';ready.value=false;progress.value=0;viewer.value++}
</script>
<template><div class="experience" :class="{'in-cockpit':s.interior.value,'cabin-finishes':cabinFinishes}"><AtelierHeader />
 <div class="scene-wrap"><ClientOnly><VehicleScene :key="viewer" @ready="ready=true" @progress="progress=$event" @error="error=$event" /></ClientOnly><div class="scene-shade" /></div>
 <div v-if="!ready||error" class="loader"><div class="wordmark">VELOCITY 3<span>AUTOMOBILI</span></div><template v-if="!error"><p>{{progress<35?t('ЗАПУСК СЦЕНЫ','INITIALIZING'):progress<65?t('ПОДГОТОВКА МАТЕРИАЛОВ','PREPARING MATERIALS'):progress<90?t('ЗАГРУЗКА АВТОМОБИЛЯ','LOADING VEHICLE'):t('НАСТРОЙКА СВЕТА','SETTING LIGHTS')}}</p><strong>{{String(progress).padStart(2,'0')}}<small>%</small></strong><div class="progress-track"><i :style="{width:progress+'%'}" /></div></template><template v-else><p>{{t('НЕ УДАЛОСЬ ЗАПУСТИТЬ ШОУРУМ','THE SHOWROOM COULD NOT START')}}</p><p>{{error}}</p><button class="outline" @click="retry">{{t('ПОВТОРИТЬ','RETRY')}}</button></template></div>
 <main><section class="hero"><div class="hero-heading"><div class="eyebrow"><i /> {{t('ЦИФРОВОЙ ШОУРУМ','THE DIGITAL ATELIER')}} <span>VELOCITY 3 / 01</span></div><h1>{{s.car.value.name.toUpperCase()}}</h1><div class="hero-sub"><p>{{t('Рассмотрите. Настройте.','Explore. Configure.')}}<br>{{t('Почувствуйте характер.','Discover its character.')}}</p><span>{{s.car.value.brand.toUpperCase()}}<br>{{s.car.value.shape===8?t('АТМОСФЕРНЫЙ V8','NATURALLY ASPIRATED V8'):s.car.value.engine.toUpperCase()}}</span></div></div>
 <div class="side-label">{{t('ИССЛЕДУЙТЕ В ДВИЖЕНИИ','DESIGNED TO BE EXPERIENCED')}}</div><div class="hero-bottom"><div class="hero-specs"><div><strong>{{s.car.value.power}}<small>{{t('Л.С.','CV')}}</small></strong><span>{{t('МОЩНОСТЬ','POWER')}}</span></div><div><strong>{{s.car.value.accel}}<small>{{t('С','S')}}</small></strong><span>{{t('0—100 КМ/Ч','0—100 KM/H')}}</span></div><div><strong>{{s.car.value.speed}}<small>{{t('КМ/Ч','KM/H')}}</small></strong><span>{{t('МАКС. СКОРОСТЬ','TOP SPEED')}}</span></div></div><a href="#showroom" class="accent-button">{{t('ОТКРЫТЬ КОНФИГУРАТОР','ENTER SHOWROOM')}} <span>↗</span></a></div><div class="hero-foot"><a href="#showroom">↓ <span>{{t('К ВЫБОРУ ОТДЕЛКИ','EXPLORE THE FINISHES')}}</span></a><span>{{t('ПЕРЕТАЩИТЕ — ПОВОРОТ','DRAG TO ROTATE')}} <b>↔</b> {{t('КОЛЕСО — МАСШТАБ','WHEEL TO ZOOM')}}</span><small>{{t('ИНТЕРАКТИВНЫЙ ПРОТОТИП','INTERACTIVE DEVELOPMENT EDITION')}}</small></div></section>
 <section id="showroom" class="showroom"><div class="showroom-title"><small>VELOCITY 3 / {{t('ВАША КОНФИГУРАЦИЯ','YOUR CONFIGURATION')}}</small><h2>{{t('Ваш характер.','Your expression.')}}</h2><p>{{t('Выберите цвет кузова, обивку и окружение.','Choose paint, upholstery and your environment.')}}</p><div class="view-controls"><button v-for="v in [{id:'front',ru:'Спереди',en:'Front'},{id:'side',ru:'Сбоку',en:'Side'},{id:'rear',ru:'Сзади',en:'Rear'}]" @click="action(()=>focus(v.id))">{{t(v.ru,v.en)}}</button></div></div>
 <div class="configurator"><div class="config-heading"><span>{{s.car.value.name.toUpperCase()}} / {{t('КОНФИГУРАТОР','CONFIGURATOR')}}</span><span>↗</span></div><div class="config-tabs" role="tablist"><button v-for="item in tabs" :id="'tab-'+item.id" role="tab" :aria-selected="tab===item.id" :aria-controls="'panel-'+item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{t(item.ru,item.en)}}</button></div><div class="config-content" role="tabpanel" :id="'panel-'+tab" :aria-labelledby="'tab-'+tab">
 <template v-if="tab==='paint'"><div class="swatches"><button v-for="p in paints" :aria-label="t(p.ru,p.en)" :title="t(p.ru,p.en)" :aria-pressed="s.paint.value===p.hex" :class="{selected:s.paint.value===p.hex}" :style="{'--swatch':p.hex}" @click="action(()=>s.paint.value=p.hex)" /></div><div class="selection-label"><span>{{paintName}}</span><small>{{t('МЕТАЛЛИК','METALLIC FINISH')}}</small></div></template>
 <template v-else-if="tab==='interior'"><small class="field-caption">{{t('ЦВЕТ ОБИВКИ','UPHOLSTERY FINISH')}}</small><div class="swatches"><button v-for="p in upholsteryColors" :aria-label="t('Обивка: '+p.ru,'Upholstery: '+p.en)" :title="t(p.ru,p.en)" :aria-pressed="s.upholstery.value===p.hex" :class="{selected:s.upholstery.value===p.hex}" :style="{'--swatch':p.hex}" @click="action(()=>s.upholstery.value=p.hex)" /></div><div class="selection-label"><span>{{upholsteryName}}</span><small>{{t('КОЖА','LEATHER')}}</small></div><button class="outline cockpit-button" @click="action(()=>s.interior.value=!s.interior.value)">{{s.interior.value?t('ВЫЙТИ ИЗ САЛОНА','EXIT INTERIOR'):t('ВОЙТИ В САЛОН','ENTER COCKPIT')}} ↗</button><p>{{t('Внутри — обзор из одной точки. Перетаскивайте для поворота взгляда.','Inside, look around from a fixed seat. Drag to turn your view.')}}</p></template>
 <template v-else-if="tab==='environment'"><small class="field-caption">{{t('ЛОКАЦИЯ','LOCATION')}}</small><div class="option-buttons location-options"><button v-for="e in environments" :aria-pressed="s.environment.value===e.id" :class="{active:s.environment.value===e.id}" @click="s.environment.value=e.id">{{t(e.ru,e.en)}}</button></div><small class="field-caption">{{t('ЦВЕТ ОКРУЖЕНИЯ','BACKGROUND COLOR')}}</small><div class="swatches background-swatches"><button v-for="p in backgrounds" :aria-label="t('Фон: '+p.ru,'Background: '+p.en)" :title="t(p.ru,p.en)" :aria-pressed="s.background.value===p.hex" :class="{selected:s.background.value===p.hex}" :style="{'--swatch':p.hex}" @click="action(()=>{s.environment.value='studio';s.background.value=p.hex})" /></div><small class="field-caption">{{t('СВЕТОВАЯ СХЕМА','LIGHTING')}}</small><div class="option-buttons"><button v-for="l in lightPresets" :class="{active:s.lighting.value===l.id}" :aria-pressed="s.lighting.value===l.id" @click="action(()=>s.lighting.value=l.id)">{{t(l.ru,l.en)}}</button></div></template>
 <template v-else><p>{{t('Крупный план настоящих деталей модели. Цвет тормозных дисков зафиксирован.','Close-ups of the model’s details. Brake rotor color is fixed.')}}</p><div class="option-buttons"><button @click="action(()=>{s.interior.value=false;focus('wheel')})">{{t('Колёса и тормоза','Wheels & brakes')}}</button><button @click="action(()=>{s.interior.value=false;focus('rear')})">{{t('Задняя оптика','Rear lights')}}</button></div></template>
 </div><div class="config-actions"><button :aria-pressed="s.doors.value" @click="action(()=>s.doors.value=!s.doors.value)">{{s.doors.value?t('ЗАКРЫТЬ ДВЕРИ','CLOSE DOORS'):t('ОТКРЫТЬ ДВЕРИ','OPEN DOORS')}} <span>↗</span></button><NuxtLink :to="'/drive/'+s.car.value.id">{{t('ПОЕЗДКА','DRIVE')}} <span>→</span></NuxtLink></div><div class="lamp-controls"><label>{{t('Передние фары','Headlights')}}<input type="checkbox" v-model="s.headlights.value"></label><label>{{t('Задние фонари','Tail lights')}}<input type="checkbox" v-model="s.taillights.value"></label></div></div>
 </section></main>
 <div v-if="s.interior.value" class="cockpit-ui"><div class="cockpit-title"><small>{{t('МЕСТО ВОДИТЕЛЯ','DRIVER’S SEAT')}}</small><h3>{{s.car.value.name}}</h3><p>{{t('Перетаскивайте, чтобы осмотреться','Drag to look around')}}</p></div><div class="cockpit-toolbar"><button class="outline" @click="cabinFinishes=!cabinFinishes">{{t('ОТДЕЛКА САЛОНА','UPHOLSTERY')}}</button><button class="outline" @click="s.interior.value=false">{{t('ВЫЙТИ','EXIT')}} ↗</button></div><div class="hotspots"><button v-for="d in interiorDetails" :class="{active:s.detail.value===d.id}" @click="inspect(d.id)">+ {{t(d.ru,d.en)}}</button><div v-if="detail" class="hotspot-card"><button @click="s.detail.value=''" :aria-label="t('Закрыть описание','Close detail')">×</button><h3>{{t(detail.ru,detail.en)}}</h3><p>{{t(detail.ruText,detail.enText)}}</p></div></div></div>
 <footer><span class="wordmark">VELOCITY 3</span><NuxtLink to="/garage">{{t('ГАРАЖ / 08','GARAGE / 08')}} ↗</NuxtLink><small><a href="https://sketchfab.com/3d-models/2011-ferrari-458-italia-bb6c7fa565c04ec59cd9d0e0a4d0098c" target="_blank" rel="noopener">Ferrari 458 Italia · Ddiaz Design</a><br>CC BY 4.0 · {{t('Независимый проект','Independent experience')}}</small><a href="#">{{t('НАВЕРХ','BACK TO TOP')}} ↑</a></footer>
</div></template>
